using System;
using System.Drawing;
using System.Drawing.Printing;
using System.IO;
using System.Security.Cryptography.X509Certificates;
using System.Windows.Forms;

namespace MiniPdf {
    internal sealed partial class MainWindow {
        Bitmap pendingSignature;
        SizeF signatureSize;
        internal Bitmap PendingSignature {get{return canvas.Mode==Tool.Image?pendingSignature:null;}}
        internal SizeF SignatureSize {get{return signatureSize;}}
        internal void BeginSignature(Bitmap image,float widthMm){if(pendingSignature!=null)pendingSignature.Dispose();pendingSignature=new Bitmap(image);signatureSize=new SizeF(widthMm*72/25.4f,widthMm*72/25.4f*image.Height/image.Width);pendingImage="";canvas.ClearSelection();SetTool(Tool.Image);Report(UiText.Get("单击放置签名，或拖框设定大小；Esc 取消。"));}
        internal void InsertSignature(Rectangle bounds){if(pendingSignature==null||Document==null)return;bool done=false;var matrix=canvas.ImageMatrix(bounds);Run(delegate{Document.AddSignature(pendingSignature,matrix);done=true;});if(!done)return;pendingSignature.Dispose();pendingSignature=null;SelectInsertedImage();Report(UiText.Get("签名已放置：拖动移动，拖动右下角缩放；右键可输入缩放比例。"));}
        void SelectInsertedImage(){SetTool(Tool.Object);canvas.Selected=Document.PickIndex(N.FPDFPage_CountObjects(Document.Page)-1);SelectionChanged();canvas.Invalidate();}
        void VisibleSignature(){if(Document==null)return;if(!Document.CanEdit){Report(UiText.Get("此文档不能编辑。"));return;}using(var dialog=new SignatureWindow((float)((canvas.ViewRotation&1)==0?Document.Width:Document.Height)*25.4f/72))if(dialog.ShowDialog(this)==DialogResult.OK)BeginSignature(dialog.Result,dialog.WidthMm);}

        void AddWatermark(){if(Document==null||!Document.CanEdit)return;using(var dialog=new WatermarkWindow(Document))if(dialog.ShowDialog(this)==DialogResult.OK)Run(delegate{Document.Watermark(dialog.Options);});}
        void RemoveWatermark(){if(Document==null||!Document.CanEdit)return;using(var dialog=new WatermarkRemovalWindow(Document))if(dialog.ShowDialog(this)==DialogResult.OK)Run(delegate{Document.RemoveWatermarkTargets(dialog.Targets);});}

        void SignWithCertificate(){if(Document==null)return;try{PdfDocument.Check(Document.CanEdit&&Document.SignatureCount==0,UiText.Get("已有签名的文档以只读方式打开，暂不支持追加签名。"));using(var dialog=new CertificateWindow())if(dialog.ShowDialog(this)==DialogResult.OK)using(var save=new SaveFileDialog{Filter=UiText.Get("PDF 文档 (*.pdf)|*.pdf"),FileName=Path.GetFileNameWithoutExtension(String.IsNullOrEmpty(Document.FilePath)?"Mini PDF":Document.FilePath)+".signed.pdf",RestoreDirectory=true,DefaultExt="pdf",AddExtension=true})if(save.ShowDialog(this)==DialogResult.OK){PdfDocument.Check(String.IsNullOrEmpty(Document.FilePath)||!String.Equals(Path.GetFullPath(save.FileName),Path.GetFullPath(Document.FilePath),StringComparison.OrdinalIgnoreCase),UiText.Get("请使用其他文件名保存签名副本。"));PdfDocument.Check(CanSaveToPath(save.FileName),UiText.Get("该文件已在另一个标签中打开，请选择其他文件名。"));UseWaitCursor=true;try{byte[] data=PdfSignatures.Sign(Document,dialog.Certificate,dialog.Reason,dialog.SigningLocation);PdfDocument.AtomicWrite(save.FileName,data,"",Document.Count);}finally{UseWaitCursor=false;}OpenDocument(save.FileName);}}catch(Exception e){MessageBox.Show(this,e.Message,UiText.Get("证书签名未完成"),MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
        void ShowSignatures(){if(Document==null)return;var reports=PdfSignatures.Inspect(Document);try{using(var form=new Form()){FormUi.Setup(form,"签名和证书",new Size(790,480));var list=new ListBox{Dock=DockStyle.Left,Width=220,BorderStyle=BorderStyle.None};var details=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=Color.White};var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,Padding=new Padding(8)};bar.Controls.Add(FormUi.Button("查看证书…",delegate{if(list.SelectedIndex>=0&&reports[list.SelectedIndex].Certificate!=null)X509Certificate2UI.DisplayCertificate(reports[list.SelectedIndex].Certificate,form.Handle);}));bar.Controls.Add(FormUi.Button("关闭",delegate{form.Close();}));form.Controls.Add(details);form.Controls.Add(list);form.Controls.Add(bar);foreach(var r in reports)list.Items.Add(r.Name);list.SelectedIndexChanged+=delegate{if(list.SelectedIndex<0)return;var r=reports[list.SelectedIndex];details.Text=r.Name+Environment.NewLine+Environment.NewLine+r.Details;if(r.Certificate!=null)details.Text+=Environment.NewLine+Environment.NewLine+r.Certificate.ToString(false);};if(reports.Count>0)list.SelectedIndex=0;else details.Text=UiText.Get("此文档没有证书数字签名。可见手写或图片签名不属于证书签名。");form.ShowDialog(this);}}finally{PdfSignatures.DisposeReports(reports);}}
        void ViewCertificateFile(){using(var file=new OpenFileDialog{Filter="Certificate (*.cer;*.crt;*.der)|*.cer;*.crt;*.der",RestoreDirectory=true})if(file.ShowDialog(this)==DialogResult.OK)try{using(var certificate=new X509Certificate2(File.ReadAllBytes(file.FileName)))X509Certificate2UI.DisplayCertificate(certificate,Handle);}catch(Exception e){MessageBox.Show(this,e.Message,UiText.Get("无法打开证书"));}}
        void AdvancedPrint(){if(Document==null)return;if(!Document.CanPrint){Report(UiText.Get("此 PDF 限制打印。"));return;}try{using(var dialog=new PrintWindow(Document))if(dialog.ShowDialog(this)==DialogResult.OK)using(var print=dialog.CreateJob())print.Print();}catch(Exception e){MessageBox.Show(this,e.Message,UiText.Get("打印未完成"),MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
        void CombineFiles(){using(var dialog=new MergeWindow(Document))if(dialog.ShowDialog(this)==DialogResult.OK){var combined=dialog.Build();TrackDocument(combined);}}
    }
}
